def f(x, y):
    return 3*x**2 + 3*y**2 - x**2 * y**2 - 8*x*y - 1

a = [0.2, 1.0, 3.732]
results = []
for i in range(len(a)):
    for j in range(i + 1, len(a)):
        results.append(f(a[i], a[j]))
print(f"Results for n=3 with {a}: {results}")

